local RS = game:GetService("RunService") local old = workspace:FindFirstChild("VolumetricClouds") if old then old:Destroy() end local F = Instance.new("Folder") F.Name = "VolumetricClouds" F.Parent = workspace local R = Random.new() local AREA, ALT, COUNT, WIND = 3500, 450, 35, Vector3.new(10, 0, 4) local LAYERS = {{1, 0.1, 0}, {1.22, 0.55, 0.05}, {1.5, 0.85, 0.1}} local function puff(root, pos, size, shade) for _, L in ipairs(LAYERS) do local p = Instance.new("Part") p.Shape = Enum.PartType.Ball p.Size = Vector3.one * math.min(size * L[1], 2048) p.Material = Enum.Material.SmoothPlastic p.Transparency = L[2] local c = math.clamp(shade + L[3], 0, 1) p.Color = Color3.new(c, c, math.min(c + 0.04, 1)) p.CastShadow = L[2] < 0.5 p.CanCollide = false p.CanTouch = false p.CanQuery = false p.Massless = true p.Anchored = false local j = Vector3.new(R:NextNumber(-1, 1), R:NextNumber(0, 1), R:NextNumber(-1, 1)) * size * 0.08 * L[1] p.CFrame = root.CFrame * CFrame.new(pos + j) local w = Instance.new("WeldConstraint") w.Part0 = root w.Part1 = p w.Parent = p p.Parent = root.Parent end end for i = 1, COUNT do local rad = R:NextNumber(90, 240) local h = rad * R:NextNumber(0.5, 0.95) local seed = R:NextNumber(0, 1000) local m = Instance.new("Model") m.Name = "Cloud" local root = Instance.new("Part") root.Name = "Root" root.Size = Vector3.one root.Transparency = 1 root.Anchored = true root.CanCollide = false root.CanTouch = false root.CanQuery = false root.CFrame = CFrame.new(R:NextNumber(-AREA, AREA), ALT + R:NextNumber(-80, 120), R:NextNumber(-AREA, AREA)) * CFrame.Angles(0, R:NextNumber(0, 6.28), 0) root.Parent = m m.PrimaryPart = root m.Parent = F for k = 1, math.floor(rad / 7) + 10 do local a = R:NextNumber(0, 6.283) local d = math.sqrt(R:NextNumber()) * rad local x, z = math.cos(a) * d * 1.35, math.sin(a) * d * 0.85 local t = d / rad local top = h * (1 - t * t) * (0.75 + 0.5 * math.noise(x / 90, z / 90, seed)) local y = R:NextNumber(0, math.max(top, 1)) local s = math.max(rad * 0.5 * (1 - t * 0.55) * R:NextNumber(0.6, 1.1), 20) local shade = 0.68 + 0.32 * math.clamp(y / h, 0, 1) puff(root, Vector3.new(x, y + s * 0.25, z), s, shade) end task.wait() end local conn conn = RS.Heartbeat:Connect(function(dt) if not F.Parent then conn:Disconnect() return end for _, m in ipairs(F:GetChildren()) do local r = m.PrimaryPart if r then local p = r.Position + WIND * dt local x, z = p.X, p.Z if x > AREA then x = x - 2 * AREA elseif x < -AREA then x = x + 2 * AREA end if z > AREA then z = z - 2 * AREA elseif z < -AREA then z = z + 2 * AREA end r.CFrame = CFrame.new(x, p.Y, z) * r.CFrame.Rotation end end end) print("Volumetric clouds spawned: " .. #F:GetDescendants() .. " instances")
